def stage(base):
    output = TICKET / "🗑️generated" / "dct-stage"
    output.mkdir(parents=True, exist_ok=True)
    manifest = {}
    for index, (relative, edits) in enumerate(DEFAULT.items()):
        path = base / relative
        source = path.read_text()
        replacement = source
        for old, new in edits:
            assert replacement.count(old) == 1, (relative, old)
            replacement = replacement.replace(old, new)
        target = output / f"{index}.rs"
        target.write_text(replacement)
        manifest[relative] = str(target)
        patch = difflib.unified_diff(source.splitlines(True), replacement.splitlines(True), "a/" + str(path), "b/" + str(path))
        (output / f"{index}.patch").write_text("".join(patch))
    (output / "stages.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n")
    return manifest


if __name__ == "__main__":
    stage(Path(sys.argv[1]))
